-- HYRO FORGE: Mathematics Curriculum
-- Migration 020: Common Core Grade 6 Math + Extensions through Grade 8
-- Utah Core Standards alignment with advanced extensions
-- Goal: Common Core as FLOOR, mastery FAR beyond state testing

-- ============================================================================
-- GRADE 6 MATHEMATICS STANDARDS (Common Core)
-- ============================================================================

-- 6.RP - Ratios and Proportional Relationships
INSERT OR IGNORE INTO hyro_learning_standards (id, domain, standard_set, standard_code, title, description, grade_level, grade_band, strand, cluster, sequence_order, is_assessed) VALUES
  ('math_6rp_a1', 'mathematics', 'common_core', '6.RP.A.1', 'Understand Ratio Concepts', 'Understand the concept of a ratio and use ratio language to describe a ratio relationship between two quantities.', 6, 'middle', 'Ratios & Proportions', 'Understand ratio concepts', 1, 1),
  ('math_6rp_a2', 'mathematics', 'common_core', '6.RP.A.2', 'Unit Rates', 'Understand the concept of a unit rate a/b associated with a ratio a:b with b ≠ 0, and use rate language in the context of a ratio relationship.', 6, 'middle', 'Ratios & Proportions', 'Understand ratio concepts', 2, 1),
  ('math_6rp_a3', 'mathematics', 'common_core', '6.RP.A.3', 'Use Ratios to Solve Problems', 'Use ratio and rate reasoning to solve real-world and mathematical problems.', 6, 'middle', 'Ratios & Proportions', 'Understand ratio concepts', 3, 1),
  ('math_6rp_a3a', 'mathematics', 'common_core', '6.RP.A.3a', 'Equivalent Ratios Tables', 'Make tables of equivalent ratios relating quantities with whole-number measurements.', 6, 'middle', 'Ratios & Proportions', 'Understand ratio concepts', 4, 1),
  ('math_6rp_a3b', 'mathematics', 'common_core', '6.RP.A.3b', 'Unit Rate Problems', 'Solve unit rate problems including those involving unit pricing and constant speed.', 6, 'middle', 'Ratios & Proportions', 'Understand ratio concepts', 5, 1),
  ('math_6rp_a3c', 'mathematics', 'common_core', '6.RP.A.3c', 'Percent Problems', 'Find a percent of a quantity as a rate per 100; solve problems involving finding the whole, given a part and the percent.', 6, 'middle', 'Ratios & Proportions', 'Understand ratio concepts', 6, 1),
  ('math_6rp_a3d', 'mathematics', 'common_core', '6.RP.A.3d', 'Ratio Reasoning with Conversions', 'Use ratio reasoning to convert measurement units; manipulate and transform units appropriately when multiplying or dividing quantities.', 6, 'middle', 'Ratios & Proportions', 'Understand ratio concepts', 7, 1);

-- 6.NS - The Number System
INSERT OR IGNORE INTO hyro_learning_standards (id, domain, standard_set, standard_code, title, description, grade_level, grade_band, strand, cluster, sequence_order, is_assessed) VALUES
  ('math_6ns_a1', 'mathematics', 'common_core', '6.NS.A.1', 'Divide Fractions', 'Interpret and compute quotients of fractions, and solve word problems involving division of fractions by fractions.', 6, 'middle', 'Number System', 'Apply and extend previous understandings of multiplication and division', 10, 1),
  ('math_6ns_b2', 'mathematics', 'common_core', '6.NS.B.2', 'Multi-digit Division', 'Fluently divide multi-digit numbers using the standard algorithm.', 6, 'middle', 'Number System', 'Compute fluently with multi-digit numbers', 11, 1),
  ('math_6ns_b3', 'mathematics', 'common_core', '6.NS.B.3', 'Multi-digit Decimal Operations', 'Fluently add, subtract, multiply, and divide multi-digit decimals using the standard algorithm for each operation.', 6, 'middle', 'Number System', 'Compute fluently with multi-digit numbers', 12, 1),
  ('math_6ns_b4', 'mathematics', 'common_core', '6.NS.B.4', 'GCF and LCM', 'Find the greatest common factor of two whole numbers less than or equal to 100 and the least common multiple of two whole numbers less than or equal to 12.', 6, 'middle', 'Number System', 'Compute fluently with multi-digit numbers', 13, 1),
  ('math_6ns_c5', 'mathematics', 'common_core', '6.NS.C.5', 'Understand Positive and Negative Numbers', 'Understand that positive and negative numbers are used together to describe quantities having opposite directions or values.', 6, 'middle', 'Number System', 'Apply and extend previous understandings of numbers to the system of rational numbers', 14, 1),
  ('math_6ns_c6', 'mathematics', 'common_core', '6.NS.C.6', 'Rational Numbers on Number Line', 'Understand a rational number as a point on the number line. Extend number line diagrams and coordinate axes.', 6, 'middle', 'Number System', 'Apply and extend previous understandings of numbers to the system of rational numbers', 15, 1),
  ('math_6ns_c7', 'mathematics', 'common_core', '6.NS.C.7', 'Order and Absolute Value', 'Understand ordering and absolute value of rational numbers.', 6, 'middle', 'Number System', 'Apply and extend previous understandings of numbers to the system of rational numbers', 16, 1),
  ('math_6ns_c8', 'mathematics', 'common_core', '6.NS.C.8', 'Coordinate Plane Problems', 'Solve real-world and mathematical problems by graphing points in all four quadrants of the coordinate plane.', 6, 'middle', 'Number System', 'Apply and extend previous understandings of numbers to the system of rational numbers', 17, 1);

-- 6.EE - Expressions and Equations
INSERT OR IGNORE INTO hyro_learning_standards (id, domain, standard_set, standard_code, title, description, grade_level, grade_band, strand, cluster, sequence_order, is_assessed) VALUES
  ('math_6ee_a1', 'mathematics', 'common_core', '6.EE.A.1', 'Exponents', 'Write and evaluate numerical expressions involving whole-number exponents.', 6, 'middle', 'Expressions & Equations', 'Apply and extend previous understandings of arithmetic to algebraic expressions', 20, 1),
  ('math_6ee_a2', 'mathematics', 'common_core', '6.EE.A.2', 'Read and Write Expressions', 'Write, read, and evaluate expressions in which letters stand for numbers.', 6, 'middle', 'Expressions & Equations', 'Apply and extend previous understandings of arithmetic to algebraic expressions', 21, 1),
  ('math_6ee_a3', 'mathematics', 'common_core', '6.EE.A.3', 'Equivalent Expressions', 'Apply the properties of operations to generate equivalent expressions.', 6, 'middle', 'Expressions & Equations', 'Apply and extend previous understandings of arithmetic to algebraic expressions', 22, 1),
  ('math_6ee_a4', 'mathematics', 'common_core', '6.EE.A.4', 'Identify Equivalent Expressions', 'Identify when two expressions are equivalent (i.e., when the two expressions name the same number regardless of which value is substituted into them).', 6, 'middle', 'Expressions & Equations', 'Apply and extend previous understandings of arithmetic to algebraic expressions', 23, 1),
  ('math_6ee_b5', 'mathematics', 'common_core', '6.EE.B.5', 'Solve Equations as Process', 'Understand solving an equation or inequality as a process of answering a question: which values from a specified set, if any, make the equation or inequality true?', 6, 'middle', 'Expressions & Equations', 'Reason about and solve one-variable equations and inequalities', 24, 1),
  ('math_6ee_b6', 'mathematics', 'common_core', '6.EE.B.6', 'Variables for Unknown Numbers', 'Use variables to represent numbers and write expressions when solving a real-world or mathematical problem.', 6, 'middle', 'Expressions & Equations', 'Reason about and solve one-variable equations and inequalities', 25, 1),
  ('math_6ee_b7', 'mathematics', 'common_core', '6.EE.B.7', 'Solve Real-World Equations', 'Solve real-world and mathematical problems by writing and solving equations of the form x + p = q and px = q for cases in which p, q and x are all nonnegative rational numbers.', 6, 'middle', 'Expressions & Equations', 'Reason about and solve one-variable equations and inequalities', 26, 1),
  ('math_6ee_b8', 'mathematics', 'common_core', '6.EE.B.8', 'Inequalities', 'Write an inequality of the form x > c or x < c to represent a constraint or condition in a real-world or mathematical problem.', 6, 'middle', 'Expressions & Equations', 'Reason about and solve one-variable equations and inequalities', 27, 1),
  ('math_6ee_c9', 'mathematics', 'common_core', '6.EE.C.9', 'Dependent and Independent Variables', 'Use variables to represent two quantities in a real-world problem that change in relationship to one another.', 6, 'middle', 'Expressions & Equations', 'Represent and analyze quantitative relationships between dependent and independent variables', 28, 1);

-- 6.G - Geometry
INSERT OR IGNORE INTO hyro_learning_standards (id, domain, standard_set, standard_code, title, description, grade_level, grade_band, strand, cluster, sequence_order, is_assessed) VALUES
  ('math_6g_a1', 'mathematics', 'common_core', '6.G.A.1', 'Area of Polygons', 'Find the area of right triangles, other triangles, special quadrilaterals, and polygons by composing into rectangles or decomposing into triangles and other shapes.', 6, 'middle', 'Geometry', 'Solve real-world and mathematical problems involving area, surface area, and volume', 30, 1),
  ('math_6g_a2', 'mathematics', 'common_core', '6.G.A.2', 'Volume with Fractions', 'Find the volume of a right rectangular prism with fractional edge lengths.', 6, 'middle', 'Geometry', 'Solve real-world and mathematical problems involving area, surface area, and volume', 31, 1),
  ('math_6g_a3', 'mathematics', 'common_core', '6.G.A.3', 'Polygons in Coordinate Plane', 'Draw polygons in the coordinate plane given coordinates for the vertices.', 6, 'middle', 'Geometry', 'Solve real-world and mathematical problems involving area, surface area, and volume', 32, 1),
  ('math_6g_a4', 'mathematics', 'common_core', '6.G.A.4', 'Surface Area with Nets', 'Represent three-dimensional figures using nets made up of rectangles and triangles, and use the nets to find the surface area of these figures.', 6, 'middle', 'Geometry', 'Solve real-world and mathematical problems involving area, surface area, and volume', 33, 1);

-- 6.SP - Statistics and Probability
INSERT OR IGNORE INTO hyro_learning_standards (id, domain, standard_set, standard_code, title, description, grade_level, grade_band, strand, cluster, sequence_order, is_assessed) VALUES
  ('math_6sp_a1', 'mathematics', 'common_core', '6.SP.A.1', 'Statistical Questions', 'Recognize a statistical question as one that anticipates variability in the data related to the question and accounts for it in the answers.', 6, 'middle', 'Statistics & Probability', 'Develop understanding of statistical variability', 40, 1),
  ('math_6sp_a2', 'mathematics', 'common_core', '6.SP.A.2', 'Distribution Description', 'Understand that a set of data collected to answer a statistical question has a distribution which can be described by its center, spread, and overall shape.', 6, 'middle', 'Statistics & Probability', 'Develop understanding of statistical variability', 41, 1),
  ('math_6sp_a3', 'mathematics', 'common_core', '6.SP.A.3', 'Center and Variation', 'Recognize that a measure of center for a numerical data set summarizes all of its values with a single number, while a measure of variation describes how its values vary with a single number.', 6, 'middle', 'Statistics & Probability', 'Develop understanding of statistical variability', 42, 1),
  ('math_6sp_b4', 'mathematics', 'common_core', '6.SP.B.4', 'Display Data', 'Display numerical data in plots on a number line, including dot plots, histograms, and box plots.', 6, 'middle', 'Statistics & Probability', 'Summarize and describe distributions', 43, 1),
  ('math_6sp_b5', 'mathematics', 'common_core', '6.SP.B.5', 'Summarize Data Sets', 'Summarize numerical data sets in relation to their context.', 6, 'middle', 'Statistics & Probability', 'Summarize and describe distributions', 44, 1);

-- ============================================================================
-- GRADE 7 MATHEMATICS STANDARDS (Common Core) - EXTENSION
-- ============================================================================

INSERT OR IGNORE INTO hyro_learning_standards (id, domain, standard_set, standard_code, title, description, grade_level, grade_band, strand, cluster, sequence_order, is_assessed, is_extension) VALUES
  ('math_7rp_a1', 'mathematics', 'common_core', '7.RP.A.1', 'Unit Rates with Fractions', 'Compute unit rates associated with ratios of fractions, including ratios of lengths, areas and other quantities measured in like or different units.', 7, 'middle', 'Ratios & Proportions', 'Analyze proportional relationships', 50, 1, 1),
  ('math_7rp_a2', 'mathematics', 'common_core', '7.RP.A.2', 'Recognize Proportional Relationships', 'Recognize and represent proportional relationships between quantities.', 7, 'middle', 'Ratios & Proportions', 'Analyze proportional relationships', 51, 1, 1),
  ('math_7rp_a3', 'mathematics', 'common_core', '7.RP.A.3', 'Multi-step Ratio Problems', 'Use proportional relationships to solve multistep ratio and percent problems.', 7, 'middle', 'Ratios & Proportions', 'Analyze proportional relationships', 52, 1, 1),
  ('math_7ns_a1', 'mathematics', 'common_core', '7.NS.A.1', 'Add/Subtract Rational Numbers', 'Apply and extend previous understandings of addition and subtraction to add and subtract rational numbers.', 7, 'middle', 'Number System', 'Apply operations with rational numbers', 55, 1, 1),
  ('math_7ns_a2', 'mathematics', 'common_core', '7.NS.A.2', 'Multiply/Divide Rational Numbers', 'Apply and extend previous understandings of multiplication and division and of fractions to multiply and divide rational numbers.', 7, 'middle', 'Number System', 'Apply operations with rational numbers', 56, 1, 1),
  ('math_7ns_a3', 'mathematics', 'common_core', '7.NS.A.3', 'Solve Real-World Problems', 'Solve real-world and mathematical problems involving the four operations with rational numbers.', 7, 'middle', 'Number System', 'Apply operations with rational numbers', 57, 1, 1),
  ('math_7ee_a1', 'mathematics', 'common_core', '7.EE.A.1', 'Linear Expressions', 'Apply properties of operations as strategies to add, subtract, factor, and expand linear expressions with rational coefficients.', 7, 'middle', 'Expressions & Equations', 'Use properties of operations to generate equivalent expressions', 60, 1, 1),
  ('math_7ee_a2', 'mathematics', 'common_core', '7.EE.A.2', 'Rewrite Expressions', 'Understand that rewriting an expression in different forms in a problem context can shed light on the problem and how the quantities in it are related.', 7, 'middle', 'Expressions & Equations', 'Use properties of operations to generate equivalent expressions', 61, 1, 1),
  ('math_7ee_b3', 'mathematics', 'common_core', '7.EE.B.3', 'Multi-step Problems', 'Solve multi-step real-life and mathematical problems posed with positive and negative rational numbers in any form.', 7, 'middle', 'Expressions & Equations', 'Solve real-life and mathematical problems', 62, 1, 1),
  ('math_7ee_b4', 'mathematics', 'common_core', '7.EE.B.4', 'Construct and Solve Equations', 'Use variables to represent quantities in a real-world or mathematical problem, and construct simple equations and inequalities to solve problems.', 7, 'middle', 'Expressions & Equations', 'Solve real-life and mathematical problems', 63, 1, 1),
  ('math_7g_a1', 'mathematics', 'common_core', '7.G.A.1', 'Scale Drawings', 'Solve problems involving scale drawings of geometric figures, including computing actual lengths and areas from a scale drawing and reproducing a scale drawing at a different scale.', 7, 'middle', 'Geometry', 'Draw, construct, and describe geometrical figures', 70, 1, 1),
  ('math_7g_a2', 'mathematics', 'common_core', '7.G.A.2', 'Construct Triangles', 'Draw (freehand, with ruler and protractor, and with technology) geometric shapes with given conditions. Focus on constructing triangles from three measures of angles or sides.', 7, 'middle', 'Geometry', 'Draw, construct, and describe geometrical figures', 71, 1, 1),
  ('math_7g_b4', 'mathematics', 'common_core', '7.G.B.4', 'Circles', 'Know the formulas for the area and circumference of a circle and use them to solve problems.', 7, 'middle', 'Geometry', 'Solve real-life and mathematical problems involving angle measure, area, surface area, and volume', 72, 1, 1),
  ('math_7g_b5', 'mathematics', 'common_core', '7.G.B.5', 'Angle Relationships', 'Use facts about supplementary, complementary, vertical, and adjacent angles in a multi-step problem to write and solve simple equations for an unknown angle in a figure.', 7, 'middle', 'Geometry', 'Solve real-life and mathematical problems involving angle measure, area, surface area, and volume', 73, 1, 1),
  ('math_7g_b6', 'mathematics', 'common_core', '7.G.B.6', 'Area, Volume, Surface Area', 'Solve real-world and mathematical problems involving area, volume and surface area of two- and three-dimensional objects composed of triangles, quadrilaterals, polygons, cubes, and right prisms.', 7, 'middle', 'Geometry', 'Solve real-life and mathematical problems involving angle measure, area, surface area, and volume', 74, 1, 1),
  ('math_7sp_a1', 'mathematics', 'common_core', '7.SP.A.1', 'Sampling', 'Understand that statistics can be used to gain information about a population by examining a sample of the population.', 7, 'middle', 'Statistics & Probability', 'Use random sampling to draw inferences about a population', 80, 1, 1),
  ('math_7sp_b3', 'mathematics', 'common_core', '7.SP.B.3', 'Compare Distributions', 'Informally assess the degree of visual overlap of two numerical data distributions with similar variabilities.', 7, 'middle', 'Statistics & Probability', 'Draw informal comparative inferences about two populations', 81, 1, 1),
  ('math_7sp_c5', 'mathematics', 'common_core', '7.SP.C.5', 'Probability Concepts', 'Understand that the probability of a chance event is a number between 0 and 1 that expresses the likelihood of the event occurring.', 7, 'middle', 'Statistics & Probability', 'Investigate chance processes and develop, use, and evaluate probability models', 82, 1, 1),
  ('math_7sp_c6', 'mathematics', 'common_core', '7.SP.C.6', 'Experimental Probability', 'Approximate the probability of a chance event by collecting data on the chance process that produces it and observing its long-run relative frequency.', 7, 'middle', 'Statistics & Probability', 'Investigate chance processes and develop, use, and evaluate probability models', 83, 1, 1),
  ('math_7sp_c7', 'mathematics', 'common_core', '7.SP.C.7', 'Probability Models', 'Develop a probability model and use it to find probabilities of events.', 7, 'middle', 'Statistics & Probability', 'Investigate chance processes and develop, use, and evaluate probability models', 84, 1, 1),
  ('math_7sp_c8', 'mathematics', 'common_core', '7.SP.C.8', 'Compound Events', 'Find probabilities of compound events using organized lists, tables, tree diagrams, and simulation.', 7, 'middle', 'Statistics & Probability', 'Investigate chance processes and develop, use, and evaluate probability models', 85, 1, 1);

-- ============================================================================
-- GRADE 8 MATHEMATICS STANDARDS (Common Core) - ADVANCED EXTENSION
-- ============================================================================

INSERT OR IGNORE INTO hyro_learning_standards (id, domain, standard_set, standard_code, title, description, grade_level, grade_band, strand, cluster, sequence_order, is_assessed, is_extension) VALUES
  ('math_8ns_a1', 'mathematics', 'common_core', '8.NS.A.1', 'Irrational Numbers', 'Know that numbers that are not rational are called irrational. Understand informally that every number has a decimal expansion.', 8, 'middle', 'Number System', 'Know that there are numbers that are not rational', 90, 1, 1),
  ('math_8ns_a2', 'mathematics', 'common_core', '8.NS.A.2', 'Approximate Irrationals', 'Use rational approximations of irrational numbers to compare the size of irrational numbers, locate them approximately on a number line diagram.', 8, 'middle', 'Number System', 'Know that there are numbers that are not rational', 91, 1, 1),
  ('math_8ee_a1', 'mathematics', 'common_core', '8.EE.A.1', 'Integer Exponents', 'Know and apply the properties of integer exponents to generate equivalent numerical expressions.', 8, 'middle', 'Expressions & Equations', 'Work with radicals and integer exponents', 95, 1, 1),
  ('math_8ee_a2', 'mathematics', 'common_core', '8.EE.A.2', 'Square and Cube Roots', 'Use square root and cube root symbols to represent solutions to equations of the form x² = p and x³ = p.', 8, 'middle', 'Expressions & Equations', 'Work with radicals and integer exponents', 96, 1, 1),
  ('math_8ee_a3', 'mathematics', 'common_core', '8.EE.A.3', 'Scientific Notation', 'Use numbers expressed in the form of a single digit times an integer power of 10 to estimate very large or very small quantities.', 8, 'middle', 'Expressions & Equations', 'Work with radicals and integer exponents', 97, 1, 1),
  ('math_8ee_a4', 'mathematics', 'common_core', '8.EE.A.4', 'Operations with Scientific Notation', 'Perform operations with numbers expressed in scientific notation.', 8, 'middle', 'Expressions & Equations', 'Work with radicals and integer exponents', 98, 1, 1),
  ('math_8ee_b5', 'mathematics', 'common_core', '8.EE.B.5', 'Graph Proportional Relationships', 'Graph proportional relationships, interpreting the unit rate as the slope of the graph. Compare two different proportional relationships.', 8, 'middle', 'Expressions & Equations', 'Understand the connections between proportional relationships, lines, and linear equations', 100, 1, 1),
  ('math_8ee_b6', 'mathematics', 'common_core', '8.EE.B.6', 'Slope', 'Use similar triangles to explain why the slope m is the same between any two distinct points on a non-vertical line in the coordinate plane.', 8, 'middle', 'Expressions & Equations', 'Understand the connections between proportional relationships, lines, and linear equations', 101, 1, 1),
  ('math_8ee_c7', 'mathematics', 'common_core', '8.EE.C.7', 'Solve Linear Equations', 'Solve linear equations in one variable.', 8, 'middle', 'Expressions & Equations', 'Analyze and solve linear equations and pairs of simultaneous linear equations', 102, 1, 1),
  ('math_8ee_c8', 'mathematics', 'common_core', '8.EE.C.8', 'Systems of Equations', 'Analyze and solve pairs of simultaneous linear equations.', 8, 'middle', 'Expressions & Equations', 'Analyze and solve linear equations and pairs of simultaneous linear equations', 103, 1, 1),
  ('math_8f_a1', 'mathematics', 'common_core', '8.F.A.1', 'Function Definition', 'Understand that a function is a rule that assigns to each input exactly one output. The graph of a function is the set of ordered pairs consisting of an input and the corresponding output.', 8, 'middle', 'Functions', 'Define, evaluate, and compare functions', 110, 1, 1),
  ('math_8f_a2', 'mathematics', 'common_core', '8.F.A.2', 'Compare Functions', 'Compare properties of two functions each represented in a different way (algebraically, graphically, numerically in tables, or by verbal descriptions).', 8, 'middle', 'Functions', 'Define, evaluate, and compare functions', 111, 1, 1),
  ('math_8f_a3', 'mathematics', 'common_core', '8.F.A.3', 'Linear Functions', 'Interpret the equation y = mx + b as defining a linear function, whose graph is a straight line.', 8, 'middle', 'Functions', 'Define, evaluate, and compare functions', 112, 1, 1),
  ('math_8f_b4', 'mathematics', 'common_core', '8.F.B.4', 'Model with Functions', 'Construct a function to model a linear relationship between two quantities.', 8, 'middle', 'Functions', 'Use functions to model relationships between quantities', 113, 1, 1),
  ('math_8f_b5', 'mathematics', 'common_core', '8.F.B.5', 'Analyze Functions', 'Describe qualitatively the functional relationship between two quantities by analyzing a graph.', 8, 'middle', 'Functions', 'Use functions to model relationships between quantities', 114, 1, 1),
  ('math_8g_a1', 'mathematics', 'common_core', '8.G.A.1', 'Transformations', 'Verify experimentally the properties of rotations, reflections, and translations.', 8, 'middle', 'Geometry', 'Understand congruence and similarity using physical models, transparencies, or geometry software', 120, 1, 1),
  ('math_8g_a2', 'mathematics', 'common_core', '8.G.A.2', 'Congruence', 'Understand that a two-dimensional figure is congruent to another if the second can be obtained from the first by a sequence of rotations, reflections, and translations.', 8, 'middle', 'Geometry', 'Understand congruence and similarity using physical models, transparencies, or geometry software', 121, 1, 1),
  ('math_8g_a3', 'mathematics', 'common_core', '8.G.A.3', 'Dilations', 'Describe the effect of dilations, translations, rotations, and reflections on two-dimensional figures using coordinates.', 8, 'middle', 'Geometry', 'Understand congruence and similarity using physical models, transparencies, or geometry software', 122, 1, 1),
  ('math_8g_a4', 'mathematics', 'common_core', '8.G.A.4', 'Similarity', 'Understand that a two-dimensional figure is similar to another if the second can be obtained from the first by a sequence of rotations, reflections, translations, and dilations.', 8, 'middle', 'Geometry', 'Understand congruence and similarity using physical models, transparencies, or geometry software', 123, 1, 1),
  ('math_8g_b6', 'mathematics', 'common_core', '8.G.B.6', 'Pythagorean Theorem Proof', 'Explain a proof of the Pythagorean Theorem and its converse.', 8, 'middle', 'Geometry', 'Understand and apply the Pythagorean Theorem', 125, 1, 1),
  ('math_8g_b7', 'mathematics', 'common_core', '8.G.B.7', 'Apply Pythagorean Theorem', 'Apply the Pythagorean Theorem to determine unknown side lengths in right triangles in real-world and mathematical problems in two and three dimensions.', 8, 'middle', 'Geometry', 'Understand and apply the Pythagorean Theorem', 126, 1, 1),
  ('math_8g_b8', 'mathematics', 'common_core', '8.G.B.8', 'Distance Formula', 'Apply the Pythagorean Theorem to find the distance between two points in a coordinate system.', 8, 'middle', 'Geometry', 'Understand and apply the Pythagorean Theorem', 127, 1, 1),
  ('math_8g_c9', 'mathematics', 'common_core', '8.G.C.9', 'Volume Formulas', 'Know the formulas for the volumes of cones, cylinders, and spheres and use them to solve real-world and mathematical problems.', 8, 'middle', 'Geometry', 'Solve real-world and mathematical problems involving volume of cylinders, cones, and spheres', 128, 1, 1),
  ('math_8sp_a1', 'mathematics', 'common_core', '8.SP.A.1', 'Scatter Plots', 'Construct and interpret scatter plots for bivariate measurement data to investigate patterns of association between two quantities.', 8, 'middle', 'Statistics & Probability', 'Investigate patterns of association in bivariate data', 130, 1, 1),
  ('math_8sp_a2', 'mathematics', 'common_core', '8.SP.A.2', 'Line of Best Fit', 'Know that straight lines are widely used to model relationships between two quantitative variables.', 8, 'middle', 'Statistics & Probability', 'Investigate patterns of association in bivariate data', 131, 1, 1),
  ('math_8sp_a3', 'mathematics', 'common_core', '8.SP.A.3', 'Slope and Intercept', 'Use the equation of a linear model to solve problems in the context of bivariate measurement data, interpreting the slope and intercept.', 8, 'middle', 'Statistics & Probability', 'Investigate patterns of association in bivariate data', 132, 1, 1),
  ('math_8sp_a4', 'mathematics', 'common_core', '8.SP.A.4', 'Two-Way Tables', 'Understand that patterns of association can also be seen in bivariate categorical data by displaying frequencies and relative frequencies in a two-way table.', 8, 'middle', 'Statistics & Probability', 'Investigate patterns of association in bivariate data', 133, 1, 1);

