INSERT OR IGNORE INTO hyro_learning_standards (id, domain, standard_set, standard_code, title, description, grade_level, grade_band, strand, cluster, sequence_order, is_assessed, is_extension) VALUES
  ('math_adv_algebra_intro', 'mathematics', 'hyro_advanced', 'ADV.ALG.1', 'Introduction to Algebra', 'Foundational algebraic thinking including pattern recognition, function notation, and abstract reasoning.', NULL, 'advanced', 'Algebra', 'Algebraic Foundations', 200, 0, 1),
  ('math_adv_quadratics', 'mathematics', 'hyro_advanced', 'ADV.ALG.2', 'Quadratic Expressions', 'Introduction to quadratic expressions, factoring, and the quadratic formula.', NULL, 'advanced', 'Algebra', 'Quadratics', 201, 0, 1),
  ('math_adv_exponential', 'mathematics', 'hyro_advanced', 'ADV.ALG.3', 'Exponential Functions', 'Understanding exponential growth and decay, compound interest, and exponential equations.', NULL, 'advanced', 'Algebra', 'Exponential Functions', 202, 0, 1),
  ('math_adv_logic', 'mathematics', 'hyro_advanced', 'ADV.LOG.1', 'Mathematical Logic', 'Introduction to formal logic, truth tables, and logical reasoning in mathematics.', NULL, 'advanced', 'Logic', 'Foundations', 210, 0, 1),
  ('math_adv_proofs', 'mathematics', 'hyro_advanced', 'ADV.LOG.2', 'Introduction to Proofs', 'Basic proof techniques including direct proof, proof by contradiction, and mathematical induction.', NULL, 'advanced', 'Logic', 'Proofs', 211, 0, 1),
  ('math_adv_number_theory', 'mathematics', 'hyro_advanced', 'ADV.NT.1', 'Number Theory Basics', 'Prime numbers, divisibility rules, modular arithmetic, and cryptographic applications.', NULL, 'advanced', 'Number Theory', 'Foundations', 220, 0, 1),
  ('math_adv_combinatorics', 'mathematics', 'hyro_advanced', 'ADV.COMB.1', 'Combinatorics', 'Permutations, combinations, counting principles, and probability connections.', NULL, 'advanced', 'Discrete Math', 'Combinatorics', 230, 0, 1),
  ('math_adv_geometry_proofs', 'mathematics', 'hyro_advanced', 'ADV.GEO.1', 'Geometric Proofs', 'Formal geometric proofs, triangle congruence theorems, and logical reasoning in geometry.', NULL, 'advanced', 'Geometry', 'Proofs', 240, 0, 1),
  ('math_adv_trig_intro', 'mathematics', 'hyro_advanced', 'ADV.TRIG.1', 'Introduction to Trigonometry', 'Right triangle trigonometry, sine, cosine, tangent, and real-world applications.', NULL, 'advanced', 'Trigonometry', 'Foundations', 250, 0, 1);

