-- 6.RP Topics - Ratios and Proportional Relationships
INSERT OR IGNORE INTO hyro_curriculum_topics (id, domain, standard_id, topic, description, learning_objectives, difficulty_tier, estimated_minutes) VALUES
  ('topic_math_ratio_intro', 'mathematics', 'math_6rp_a1', 'Introduction to Ratios', 'Understanding what ratios are and how to express them', '["Define ratio as a comparison of two quantities", "Express ratios in three forms: a:b, a/b, and a to b", "Identify ratios in real-world contexts"]', 1, 20),
  ('topic_math_ratio_language', 'mathematics', 'math_6rp_a1', 'Ratio Language', 'Using proper mathematical language to describe ratios', '["Use phrases like for every, for each, per", "Distinguish between part-to-part and part-to-whole ratios", "Translate between verbal and symbolic ratio representations"]', 1, 15),
  ('topic_math_equivalent_ratios', 'mathematics', 'math_6rp_a3a', 'Equivalent Ratios', 'Finding and recognizing equivalent ratios', '["Generate equivalent ratios by multiplying or dividing", "Determine if two ratios are equivalent", "Use ratio tables to organize equivalent ratios"]', 2, 25),
  ('topic_math_ratio_tables', 'mathematics', 'math_6rp_a3a', 'Ratio Tables', 'Creating and using ratio tables to solve problems', '["Construct ratio tables from problem contexts", "Use ratio tables to find missing values", "Identify patterns in ratio tables"]', 2, 30),
  ('topic_math_unit_rate_concept', 'mathematics', 'math_6rp_a2', 'Understanding Unit Rates', 'The concept of unit rate as a ratio with denominator 1', '["Define unit rate as a rate per one unit", "Calculate unit rates from given ratios", "Interpret unit rates in context"]', 2, 25),
  ('topic_math_unit_rate_problems', 'mathematics', 'math_6rp_a3b', 'Solving Unit Rate Problems', 'Applying unit rates to solve real-world problems', '["Use unit rates to compare prices (unit pricing)", "Solve constant speed problems using unit rates", "Choose the better deal using unit rate comparisons"]', 2, 30),
  ('topic_math_percent_concept', 'mathematics', 'math_6rp_a3c', 'Understanding Percent', 'Percent as a rate per 100', '["Define percent as per hundred", "Convert between fractions, decimals, and percents", "Recognize common percent equivalents"]', 2, 25),
  ('topic_math_percent_of_number', 'mathematics', 'math_6rp_a3c', 'Finding Percent of a Number', 'Calculating a percent of a quantity', '["Calculate percent of a number using multiplication", "Use proportional reasoning for percent problems", "Estimate percents mentally"]', 2, 30),
  ('topic_math_percent_problems', 'mathematics', 'math_6rp_a3c', 'Percent Word Problems', 'Solving various percent problem types', '["Find the part given whole and percent", "Find the whole given part and percent", "Find the percent given part and whole"]', 3, 35),
  ('topic_math_unit_conversion', 'mathematics', 'math_6rp_a3d', 'Unit Conversion', 'Converting between measurement units using ratios', '["Convert within the same measurement system", "Set up and solve conversion proportions", "Use dimensional analysis for multi-step conversions"]', 2, 30);

-- 6.NS Topics - The Number System
INSERT OR IGNORE INTO hyro_curriculum_topics (id, domain, standard_id, topic, description, learning_objectives, difficulty_tier, estimated_minutes) VALUES
  ('topic_math_divide_fractions_concept', 'mathematics', 'math_6ns_a1', 'Understanding Fraction Division', 'The meaning of dividing fractions', '["Interpret division of fractions using models", "Understand keep-change-flip rule conceptually", "Relate fraction division to multiplication"]', 2, 30),
  ('topic_math_divide_fractions_procedure', 'mathematics', 'math_6ns_a1', 'Dividing Fractions Procedure', 'Computing quotients of fractions', '["Apply the standard algorithm for fraction division", "Divide mixed numbers", "Simplify quotients"]', 2, 25),
  ('topic_math_divide_fractions_word', 'mathematics', 'math_6ns_a1', 'Fraction Division Word Problems', 'Solving real-world problems with fraction division', '["Identify when to divide fractions in context", "Set up fraction division problems from word problems", "Interpret quotients in context"]', 3, 35),
  ('topic_math_long_division', 'mathematics', 'math_6ns_b2', 'Long Division Fluency', 'Dividing multi-digit numbers efficiently', '["Apply standard long division algorithm", "Check division with multiplication", "Interpret remainders appropriately"]', 2, 30),
  ('topic_math_decimal_add_sub', 'mathematics', 'math_6ns_b3', 'Adding and Subtracting Decimals', 'Computing with decimal numbers', '["Align decimal points for addition/subtraction", "Add and subtract decimals fluently", "Estimate decimal sums and differences"]', 1, 20),
  ('topic_math_decimal_mult', 'mathematics', 'math_6ns_b3', 'Multiplying Decimals', 'Multiplying decimal numbers', '["Apply the standard algorithm for decimal multiplication", "Place decimal point correctly in products", "Estimate decimal products"]', 2, 25),
  ('topic_math_decimal_div', 'mathematics', 'math_6ns_b3', 'Dividing Decimals', 'Dividing decimal numbers', '["Divide decimals by whole numbers", "Divide decimals by decimals", "Round quotients appropriately"]', 2, 30),
  ('topic_math_gcf', 'mathematics', 'math_6ns_b4', 'Greatest Common Factor', 'Finding the GCF of two numbers', '["List factors of numbers systematically", "Identify common factors", "Find GCF using various methods"]', 2, 25),
  ('topic_math_lcm', 'mathematics', 'math_6ns_b4', 'Least Common Multiple', 'Finding the LCM of two numbers', '["List multiples of numbers", "Identify common multiples", "Find LCM using various methods"]', 2, 25),
  ('topic_math_gcf_lcm_problems', 'mathematics', 'math_6ns_b4', 'GCF and LCM Applications', 'Using GCF and LCM to solve problems', '["Apply GCF to simplify fractions", "Apply LCM to find common denominators", "Solve word problems requiring GCF or LCM"]', 3, 30),
  ('topic_math_integers_intro', 'mathematics', 'math_6ns_c5', 'Introduction to Integers', 'Understanding positive and negative numbers', '["Understand integers as positive, negative, and zero", "Represent integers on a number line", "Interpret integers in real-world contexts"]', 1, 20),
  ('topic_math_opposites', 'mathematics', 'math_6ns_c5', 'Opposites and Zero', 'Understanding opposite numbers and zero', '["Define and find opposites of numbers", "Understand that opposites sum to zero", "Locate opposites on the number line"]', 1, 15),
  ('topic_math_rational_numberline', 'mathematics', 'math_6ns_c6', 'Rational Numbers on Number Line', 'Placing rational numbers on the number line', '["Plot positive and negative fractions", "Plot positive and negative decimals", "Identify positions between integers"]', 2, 25),
  ('topic_math_coordinate_plane', 'mathematics', 'math_6ns_c6', 'The Coordinate Plane', 'Understanding the four-quadrant coordinate plane', '["Identify quadrants and axes", "Plot ordered pairs in all quadrants", "Identify coordinates of plotted points"]', 2, 25),
  ('topic_math_ordering_rationals', 'mathematics', 'math_6ns_c7', 'Ordering Rational Numbers', 'Comparing and ordering positive and negative numbers', '["Compare rational numbers using inequality symbols", "Order sets of rational numbers", "Use number line to justify comparisons"]', 2, 25),
  ('topic_math_absolute_value', 'mathematics', 'math_6ns_c7', 'Absolute Value', 'Understanding and computing absolute value', '["Define absolute value as distance from zero", "Compute absolute value of numbers", "Compare absolute values"]', 2, 20),
  ('topic_math_coordinate_problems', 'mathematics', 'math_6ns_c8', 'Coordinate Plane Problems', 'Solving problems on the coordinate plane', '["Find distances on the coordinate plane", "Reflect points across axes", "Solve real-world problems using coordinates"]', 3, 35);

-- 6.EE Topics - Expressions and Equations
INSERT OR IGNORE INTO hyro_curriculum_topics (id, domain, standard_id, topic, description, learning_objectives, difficulty_tier, estimated_minutes) VALUES
  ('topic_math_exponents_intro', 'mathematics', 'math_6ee_a1', 'Introduction to Exponents', 'Understanding exponential notation', '["Write repeated multiplication using exponents", "Evaluate expressions with exponents", "Understand base and exponent terminology"]', 1, 20),
  ('topic_math_order_operations', 'mathematics', 'math_6ee_a1', 'Order of Operations with Exponents', 'Evaluating expressions with PEMDAS', '["Apply order of operations correctly", "Evaluate expressions with parentheses and exponents", "Identify common order of operations errors"]', 2, 25),
  ('topic_math_variables_intro', 'mathematics', 'math_6ee_a2', 'Introduction to Variables', 'Understanding variables as placeholders', '["Understand that letters can represent numbers", "Evaluate expressions for given variable values", "Distinguish between variables and constants"]', 1, 20),
  ('topic_math_write_expressions', 'mathematics', 'math_6ee_a2', 'Writing Algebraic Expressions', 'Translating words to algebraic expressions', '["Translate verbal phrases to expressions", "Identify key words for operations", "Write expressions for real-world situations"]', 2, 30),
  ('topic_math_properties_operations', 'mathematics', 'math_6ee_a3', 'Properties of Operations', 'Using commutative, associative, and distributive properties', '["Identify and apply the commutative property", "Identify and apply the associative property", "Apply the distributive property"]', 2, 30),
  ('topic_math_equivalent_expressions', 'mathematics', 'math_6ee_a4', 'Generating Equivalent Expressions', 'Creating and identifying equivalent expressions', '["Use properties to create equivalent expressions", "Combine like terms", "Determine if two expressions are equivalent"]', 2, 30),
  ('topic_math_equations_intro', 'mathematics', 'math_6ee_b5', 'Introduction to Equations', 'Understanding equations and solutions', '["Define equation as a statement of equality", "Understand solution as a value that makes equation true", "Test values to check if they are solutions"]', 1, 20),
  ('topic_math_write_equations', 'mathematics', 'math_6ee_b6', 'Writing Equations', 'Representing situations with equations', '["Write equations from word problems", "Use variables appropriately in equations", "Translate between verbal and symbolic forms"]', 2, 30),
  ('topic_math_solve_add_sub', 'mathematics', 'math_6ee_b7', 'Solving Addition/Subtraction Equations', 'Solving one-step equations', '["Solve x + p = q using inverse operations", "Solve x - p = q using inverse operations", "Check solutions by substitution"]', 2, 25),
  ('topic_math_solve_mult_div', 'mathematics', 'math_6ee_b7', 'Solving Multiplication/Division Equations', 'Solving one-step equations', '["Solve px = q using inverse operations", "Solve x/p = q using inverse operations", "Interpret solutions in context"]', 2, 25),
  ('topic_math_inequalities_intro', 'mathematics', 'math_6ee_b8', 'Introduction to Inequalities', 'Understanding and writing inequalities', '["Understand inequality symbols", "Write inequalities from verbal descriptions", "Graph inequalities on number line"]', 2, 25),
  ('topic_math_dependent_independent', 'mathematics', 'math_6ee_c9', 'Dependent and Independent Variables', 'Understanding variable relationships', '["Identify independent and dependent variables", "Write equations showing relationships", "Create tables showing relationships"]', 2, 30);

