-- ============================================================================
-- QUESTION BANK - MATHEMATICS GRADE 6
-- Comprehensive question set with varied difficulty and types
-- ============================================================================

-- Ratios and Proportional Relationships Questions
INSERT OR IGNORE INTO hyro_question_bank (id, domain, standard_id, topic_id, question_type, question_text, answer_options, correct_answer, explanation, difficulty, difficulty_tier, bloom_level, dok_level, hints) VALUES
  -- Basic Ratio Questions (Tier 1)
  ('q_math_ratio_001', 'mathematics', 'math_6rp_a1', 'topic_math_ratio_intro', 'multiple_choice', 'In a bag of marbles, there are 4 red marbles and 6 blue marbles. What is the ratio of red marbles to blue marbles?', '["4:6", "6:4", "4:10", "2:5"]', '4:6', 'The ratio of red to blue is the number of red (4) compared to the number of blue (6), written as 4:6. This can also be simplified to 2:3.', 25, 1, 'remember', 1, '["Count the red marbles first", "Count the blue marbles second", "Write them in order: red to blue"]'),
  ('q_math_ratio_002', 'mathematics', 'math_6rp_a1', 'topic_math_ratio_intro', 'multiple_choice', 'Which of the following represents the same ratio as 3:5?', '["6:10", "5:3", "9:12", "3:10"]', '6:10', 'To find an equivalent ratio, multiply both parts by the same number. 3×2=6 and 5×2=10, so 6:10 is equivalent to 3:5.', 30, 1, 'understand', 2, '["Try multiplying both parts of 3:5 by 2", "Check if the fraction 6/10 equals 3/5"]'),
  ('q_math_ratio_003', 'mathematics', 'math_6rp_a1', 'topic_math_ratio_intro', 'short_answer', 'A recipe calls for 2 cups of flour for every 3 cups of sugar. Write this as a ratio of flour to sugar.', NULL, '2:3', 'The ratio is flour to sugar, so we write the flour amount first (2) then the sugar amount (3), giving us 2:3.', 20, 1, 'remember', 1, '["What comes first in flour to sugar?", "Write the flour amount, then the sugar amount"]'),
  ('q_math_ratio_004', 'mathematics', 'math_6rp_a1', 'topic_math_ratio_language', 'multiple_choice', 'The ratio of boys to girls in a class is 3 to 5. If there are 15 boys, how many girls are there?', '["9", "20", "25", "30"]', '25', 'Set up the proportion: 3/5 = 15/x. If 3 boys correspond to 5 girls, then 15 boys (3×5) correspond to 25 girls (5×5).', 40, 2, 'apply', 2, '["What number times 3 gives 15?", "Multiply 5 by that same number"]'),

  -- Unit Rate Questions (Tier 2)
  ('q_math_unit_rate_001', 'mathematics', 'math_6rp_a2', 'topic_math_unit_rate_concept', 'multiple_choice', 'A car travels 180 miles in 3 hours. What is the unit rate in miles per hour?', '["60 miles per hour", "540 miles per hour", "3 miles per hour", "180 miles per hour"]', '60 miles per hour', 'Unit rate means per one hour. Divide 180 miles by 3 hours: 180÷3 = 60 miles per hour.', 35, 2, 'apply', 2, '["Unit rate is per ONE hour", "Divide the miles by the hours"]'),
  ('q_math_unit_rate_002', 'mathematics', 'math_6rp_a3b', 'topic_math_unit_rate_problems', 'multiple_choice', 'Store A sells 5 apples for $3.00. Store B sells 8 apples for $5.00. Which store has the better price per apple?', '["Store A ($0.60 per apple)", "Store B ($0.625 per apple)", "They are the same price", "Cannot be determined"]', 'Store A ($0.60 per apple)', 'Store A: $3.00÷5 = $0.60 per apple. Store B: $5.00÷8 = $0.625 per apple. Store A is cheaper.', 45, 2, 'analyze', 3, '["Find the price per apple at each store", "Divide the total price by the number of apples", "Compare the unit prices"]'),
  ('q_math_unit_rate_003', 'mathematics', 'math_6rp_a3b', 'topic_math_unit_rate_problems', 'short_answer', 'A printer prints 45 pages in 5 minutes. How many pages does it print per minute?', NULL, '9', 'Unit rate = 45 pages ÷ 5 minutes = 9 pages per minute.', 30, 2, 'apply', 2, '["Divide pages by minutes"]'),

  -- Percent Questions (Tier 2-3)
  ('q_math_percent_001', 'mathematics', 'math_6rp_a3c', 'topic_math_percent_concept', 'multiple_choice', 'What is 25% expressed as a fraction in lowest terms?', '["1/4", "1/25", "25/10", "2/5"]', '1/4', '25% means 25 per 100, or 25/100. Simplified: 25/100 = 1/4.', 30, 2, 'understand', 1, '["Percent means per 100", "Write as a fraction over 100", "Simplify by dividing numerator and denominator by 25"]'),
  ('q_math_percent_002', 'mathematics', 'math_6rp_a3c', 'topic_math_percent_of_number', 'multiple_choice', 'What is 30% of 80?', '["24", "30", "50", "110"]', '24', '30% of 80 = 0.30 × 80 = 24. Or: (30/100) × 80 = 2400/100 = 24.', 35, 2, 'apply', 2, '["Convert 30% to a decimal (0.30)", "Multiply by 80"]'),
  ('q_math_percent_003', 'mathematics', 'math_6rp_a3c', 'topic_math_percent_problems', 'multiple_choice', 'A shirt originally costs $40. It is on sale for 15% off. What is the sale price?', '["$34", "$25", "$6", "$46"]', '$34', 'Discount = 15% of $40 = 0.15 × 40 = $6. Sale price = $40 - $6 = $34.', 45, 2, 'apply', 2, '["First find 15% of $40", "Then subtract from the original price"]'),
  ('q_math_percent_004', 'mathematics', 'math_6rp_a3c', 'topic_math_percent_problems', 'multiple_choice', '18 is what percent of 72?', '["25%", "18%", "54%", "4%"]', '25%', 'Percent = (part/whole) × 100 = (18/72) × 100 = 0.25 × 100 = 25%.', 50, 3, 'apply', 2, '["Divide the part by the whole", "Multiply by 100 to get the percent"]'),
  ('q_math_percent_005', 'mathematics', 'math_6rp_a3c', 'topic_math_percent_problems', 'short_answer', 'If 40% of a number is 28, what is the number?', NULL, '70', 'Let x = the number. 0.40x = 28. x = 28 ÷ 0.40 = 70.', 55, 3, 'apply', 3, '["Set up equation: 40% of x = 28", "Divide 28 by 0.40"]'),

  -- Fraction Division Questions
  ('q_math_frac_div_001', 'mathematics', 'math_6ns_a1', 'topic_math_divide_fractions_procedure', 'multiple_choice', 'What is 2/3 ÷ 1/4?', '["8/3", "2/12", "1/6", "8/12"]', '8/3', 'To divide fractions, multiply by the reciprocal: 2/3 ÷ 1/4 = 2/3 × 4/1 = 8/3.', 40, 2, 'apply', 2, '["Keep the first fraction", "Change division to multiplication", "Flip the second fraction"]'),
  ('q_math_frac_div_002', 'mathematics', 'math_6ns_a1', 'topic_math_divide_fractions_procedure', 'multiple_choice', 'Divide: 3/4 ÷ 2/5', '["15/8", "6/20", "5/8", "8/15"]', '15/8', '3/4 ÷ 2/5 = 3/4 × 5/2 = 15/8.', 40, 2, 'apply', 2, '["Multiply 3/4 by the reciprocal of 2/5", "The reciprocal of 2/5 is 5/2"]'),
  ('q_math_frac_div_003', 'mathematics', 'math_6ns_a1', 'topic_math_divide_fractions_word', 'multiple_choice', 'A recipe needs 3/4 cup of sugar. How many recipes can you make with 6 cups of sugar?', '["8 recipes", "4 1/2 recipes", "6 recipes", "18 recipes"]', '8 recipes', '6 ÷ 3/4 = 6 × 4/3 = 24/3 = 8 recipes.', 50, 3, 'apply', 3, '["Divide 6 by 3/4", "Write 6 as 6/1 first"]'),

  -- GCF and LCM Questions
  ('q_math_gcf_001', 'mathematics', 'math_6ns_b4', 'topic_math_gcf', 'multiple_choice', 'What is the greatest common factor (GCF) of 24 and 36?', '["12", "6", "4", "72"]', '12', 'Factors of 24: 1, 2, 3, 4, 6, 8, 12, 24. Factors of 36: 1, 2, 3, 4, 6, 9, 12, 18, 36. Common factors: 1, 2, 3, 4, 6, 12. GCF = 12.', 40, 2, 'apply', 2, '["List factors of 24", "List factors of 36", "Find the largest factor they share"]'),
  ('q_math_lcm_001', 'mathematics', 'math_6ns_b4', 'topic_math_lcm', 'multiple_choice', 'What is the least common multiple (LCM) of 4 and 6?', '["12", "24", "2", "10"]', '12', 'Multiples of 4: 4, 8, 12, 16... Multiples of 6: 6, 12, 18... The smallest common multiple is 12.', 40, 2, 'apply', 2, '["List multiples of 4", "List multiples of 6", "Find the smallest they share"]'),

  -- Integer Questions
  ('q_math_int_001', 'mathematics', 'math_6ns_c5', 'topic_math_integers_intro', 'multiple_choice', 'Which integer represents 50 feet below sea level?', '["-50", "50", "-100", "0"]', '-50', 'Below sea level is negative. 50 feet below is represented as -50.', 25, 1, 'understand', 1, '["Below sea level means negative", "The number is 50"]'),
  ('q_math_int_002', 'mathematics', 'math_6ns_c7', 'topic_math_absolute_value', 'multiple_choice', 'What is the absolute value of -8?', '["8", "-8", "0", "16"]', '8', 'Absolute value is the distance from zero, which is always positive. |-8| = 8.', 30, 2, 'understand', 1, '["Absolute value measures distance from zero", "Distance is always positive"]'),
  ('q_math_int_003', 'mathematics', 'math_6ns_c7', 'topic_math_ordering_rationals', 'multiple_choice', 'Which list shows the numbers in order from least to greatest? -5, 3, -2, 0, 1', '["−5, −2, 0, 1, 3", "3, 1, 0, −2, −5", "0, 1, −2, 3, −5", "−2, −5, 0, 1, 3"]', '−5, −2, 0, 1, 3', 'On a number line, numbers increase left to right. -5 is furthest left, then -2, then 0, 1, and 3.', 35, 2, 'apply', 2, '["Negative numbers are less than 0", "More negative = smaller value"]'),

  -- Coordinate Plane Questions
  ('q_math_coord_001', 'mathematics', 'math_6ns_c6', 'topic_math_coordinate_plane', 'multiple_choice', 'In which quadrant is the point (-3, 5) located?', '["Quadrant II", "Quadrant I", "Quadrant III", "Quadrant IV"]', 'Quadrant II', 'Quadrant II has negative x (left of y-axis) and positive y (above x-axis). (-3, 5) has x=-3 (negative) and y=5 (positive).', 40, 2, 'apply', 2, '["Check if x is positive or negative", "Check if y is positive or negative", "Quadrant II: x negative, y positive"]'),

  -- Expressions and Equations Questions
  ('q_math_exp_001', 'mathematics', 'math_6ee_a1', 'topic_math_exponents_intro', 'multiple_choice', 'What is the value of 2⁴?', '["16", "8", "6", "24"]', '16', '2⁴ means 2 × 2 × 2 × 2 = 16.', 25, 1, 'apply', 1, '["The exponent tells you how many times to multiply", "2⁴ = 2 × 2 × 2 × 2"]'),
  ('q_math_exp_002', 'mathematics', 'math_6ee_a1', 'topic_math_order_operations', 'multiple_choice', 'Evaluate: 3 + 4 × 2²', '["19", "28", "49", "14"]', '19', 'Order of operations: First 2² = 4, then 4 × 4 = 16, finally 3 + 16 = 19.', 40, 2, 'apply', 2, '["PEMDAS: Exponents before multiplication", "Multiplication before addition"]'),
  ('q_math_exp_003', 'mathematics', 'math_6ee_a2', 'topic_math_variables_intro', 'multiple_choice', 'If x = 5, what is the value of 3x + 7?', '["22", "15", "45", "37"]', '22', 'Substitute x = 5: 3(5) + 7 = 15 + 7 = 22.', 30, 2, 'apply', 2, '["Replace x with 5", "Multiply first, then add"]'),
  ('q_math_exp_004', 'mathematics', 'math_6ee_a2', 'topic_math_write_expressions', 'multiple_choice', 'Which expression represents "5 less than twice a number n"?', '["2n - 5", "5 - 2n", "2(n - 5)", "5 - n/2"]', '2n - 5', '"Twice a number" is 2n. "5 less than" means subtract 5. So: 2n - 5.', 45, 2, 'apply', 2, '["Twice a number = 2n", "Less than means subtract from"]'),
  ('q_math_exp_005', 'mathematics', 'math_6ee_a3', 'topic_math_properties_operations', 'multiple_choice', 'Use the distributive property to expand: 4(x + 3)', '["4x + 12", "4x + 3", "x + 12", "4x + 7"]', '4x + 12', 'Distributive property: 4(x + 3) = 4·x + 4·3 = 4x + 12.', 35, 2, 'apply', 2, '["Multiply 4 by each term inside", "4 × x and 4 × 3"]'),

  -- Solving Equations Questions
  ('q_math_eq_001', 'mathematics', 'math_6ee_b7', 'topic_math_solve_add_sub', 'multiple_choice', 'Solve: x + 8 = 15', '["x = 7", "x = 23", "x = 8", "x = 120"]', 'x = 7', 'Subtract 8 from both sides: x + 8 - 8 = 15 - 8, so x = 7.', 30, 2, 'apply', 2, '["What operation will undo adding 8?", "Subtract 8 from both sides"]'),
  ('q_math_eq_002', 'mathematics', 'math_6ee_b7', 'topic_math_solve_mult_div', 'multiple_choice', 'Solve: 6x = 42', '["x = 7", "x = 36", "x = 48", "x = 252"]', 'x = 7', 'Divide both sides by 6: 6x ÷ 6 = 42 ÷ 6, so x = 7.', 30, 2, 'apply', 2, '["What operation will undo multiplying by 6?", "Divide both sides by 6"]'),
  ('q_math_eq_003', 'mathematics', 'math_6ee_b7', 'topic_math_solve_mult_div', 'short_answer', 'Solve: x/5 = 9', NULL, '45', 'Multiply both sides by 5: (x/5) × 5 = 9 × 5, so x = 45.', 35, 2, 'apply', 2, '["Multiply both sides by 5"]');

-- More questions would continue for each standard and topic...
-- This gives a solid foundation of 30+ math questions

